#if ATARASY_UI_TEST_FIXTURES
import Foundation
import AtarasyCore

// Actual response pack, rebound to the explicitly synthetic list session.
// Physical challenge is recomputed only because this fixture changes the offer ID.
enum MemberReviewFixtureData {
    private static let encoded = ""
    static func value(_ name: String) throws -> [String: Any] {
        let root = try JSONSerialization.jsonObject(with: Data(base64Encoded: encoded)!) as! [String: Any]
        return (root["cases"] as! [[String: Any]]).first { $0["name"] as? String == name }!["value"] as! [String: Any]
    }
    static func detail(id: String) throws -> MemberOfferDetail {
        let binding = id == "fixture-member-physical" ? "physical" : "digital"
        var value = try value(binding + "-detail")
        value["id"] = id; value["household"] = "test-household"; value["presenter"] = "Available source"
        return try MemberOfferDetail.decode(JSONSerialization.data(withJSONObject: value), expectedID: id, household: "test-household")
    }
    static func review(detail: MemberOfferDetail) throws -> MemberReview {
        var value = try value(detail.binding + (detail.binding == "physical" ? "-known-carriage" : "-unknown-carriage"))
        value["offer"] = detail.id
        if detail.binding == "digital" {
            value["presenter"] = detail.presenter
            return .approval(try MemberApproval.decode(JSONSerialization.data(withJSONObject: value), detail: detail))
        }
        value["household"] = detail.household
        let lines = (value["lines"] as! [[String: Any]]).map { StatementLine(candidate: $0["candidate"] as! String, valence: $0["valence"] as! String, amount: ($0["amount"] as! NSNumber).int64Value, disputed: false) }
        value["challenge"] = Canonical.challenge(try Canonical.statement(offer: detail.id, carriage: (value["carriage"] as? NSNumber)?.int64Value, lines: lines))
        return .statement(try MemberStatement.decode(JSONSerialization.data(withJSONObject: value), detail: detail))
    }
}
#endif
